/** Generated by tools/gen_data.py - mission for Resonance Lattice. */
public class MissionDefinition implements MissionDefinitionPlugin {

    public void defineMission(MissionDefinitionAPI api) {
        api.initFleet(FleetSide.PLAYER, "CCS", FleetGoal.ATTACK, false);
        api.initFleet(FleetSide.ENEMY, "TTS", FleetGoal.ATTACK, true);
        api.setFleetTagline(FleetSide.PLAYER, "The Lacrimosa, alone.");
        api.setFleetTagline(FleetSide.ENEMY, "The Dies Irae, alone.");
        api.addBriefingItem("Destroy the Dies Irae");
        api.addBriefingItem("Every hit you land steals her readiness: knock her out of Bravura");
        api.addBriefingItem("Glissando through her lances; her String snaps just like yours");
        FleetMemberAPI m;
        FleetMemberAPI enemyFlag = null;
        m = api.addToFleet(FleetSide.PLAYER, "rsl_virtuoso_Soloist", FleetMemberType.SHIP, "Lacrimosa", true);
        m.getRepairTracker().setCR(1f);
        m = api.addToFleet(FleetSide.ENEMY, "rsl_virtuoso_Unbound", FleetMemberType.SHIP, "Dies Irae", false);
        enemyFlag = m;
        // the Dies Irae: a Hush core (violet seams), three S-mods, Commander Isolde Raike (level 15).
        // Done in the jar: Janino rejects ShipVariantAPI.clone() (CloneNotSupportedException not caught).
        rsl.campaign.EncoreFleets.missionDiesIrae(enemyFlag);

        float width = 8000f;
        float height = 8000f;
        api.initMap(-width / 2f, width / 2f, -height / 2f, height / 2f);
        api.addNebula(0f, 0f, 900f);
    }
}
